     3	// In-memory key-value store with the latency profile of the Redis cluster
     4	// used in production: every call yields to the event loop before it reads or
     5	// writes, so concurrent callers interleave the way they do against the real
     6	// store. Values are copied on the way in and out.
     7	class Store {
     8	  constructor() {
     9	    this.data = new Map();
    10	  }
    11	
    12	  async get(key) {
    13	    await tick();
    14	    const value = this.data.get(key);
    15	    return value === undefined ? undefined : structuredClone(value);
    16	  }
    17	
    18	  async set(key, value) {
    19	    await tick();
    20	    this.data.set(key, structuredClone(value));
    21	  }
    22	
    23	  async keys(prefix) {
    24	    await tick();
    25	    return [...this.data.keys()].filter(key => key.startsWith(prefix));
    26	  }
    27	}
    28	
    29	function tick() {
    30	  return new Promise(resolve => setImmediate(resolve));
    31	}
    32	
    33	module.exports = { Store };
