'use strict';

// Reproductions for INC-5521. Checkout workers call the service concurrently,
// so most of these start overlapping calls and check the counters afterwards.

const test = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  Store,
  InsufficientStockError,
  UnknownSkuError,
  UnknownOrderError,
  OrderStateError
} = require('../src');

// Enough store round-trips for the gap to land anywhere inside the first call.
const GAPS = [0, 1, 2, 3, 4, 5, 6, 8];

async function service(stock = { widget: 10 }, options = {}) {
  const svc = new InventoryService(options);
  for (const [sku, qty] of Object.entries(stock)) {
    await svc.addStock(sku, qty);
  }
  return svc;
}

function ticks(n) {
  let p = Promise.resolve();
  for (let i = 0; i < n; i++) {
    p = p.then(() => new Promise(resolve => setImmediate(resolve)));
  }
  return p;
}

// Starts `first`, lets `gap` event-loop turns pass, then starts `second`.
async function race(first, second, gap) {
  const a = first();
  await ticks(gap);
  const b = second();
  return Promise.allSettled([a, b]);
}

function counters(snapshot) {
  const { stock, reserved, sold } = snapshot;
  return { stock, reserved, sold };
}

function mulberry32(seed) {
  return () => {
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Same three methods as Store, but each call takes a random number of
// event-loop turns and hands out its own objects instead of copies.
class JitteryStore {
  constructor(seed) {
    this.data = new Map();
    this.random = mulberry32(seed);
  }

  async get(key) {
    await ticks(Math.floor(this.random() * 4));
    return this.data.get(key);
  }

  async set(key, value) {
    await ticks(Math.floor(this.random() * 4));
    this.data.set(key, value);
  }

  async keys(prefix) {
    await ticks(Math.floor(this.random() * 4));
    return [...this.data.keys()].filter(key => key.startsWith(prefix));
  }
}

// A Store whose reads of a key can be held until the test lets them through.
class GatedStore extends Store {
  constructor() {
    super();
    this.gates = new Map();
  }

  close(key) {
    let open;
    this.gates.set(key, new Promise(resolve => { open = resolve; }));
    return () => {
      this.gates.delete(key);
      open();
    };
  }

  async get(key) {
    await this.gates.get(key);
    return super.get(key);
  }
}

// Every SKU's counters must agree with the orders in the store.
async function assertConsistent(store, added) {
  const expected = {};
  for (const [sku, stock] of Object.entries(added)) {
    expected[sku] = { stock, reserved: 0, sold: 0 };
  }
  for (const key of await store.keys('order:')) {
    const order = await store.get(key);
    for (const { sku, qty } of order.items) {
      if (order.status === 'reserved') expected[sku].reserved += qty;
      if (order.status === 'committed') {
        expected[sku].sold += qty;
        expected[sku].stock -= qty;
      }
    }
  }
  for (const [sku, want] of Object.entries(expected)) {
    const item = await store.get(`sku:${sku}`);
    assert.deepEqual(counters(item), want, `counters for ${sku}`);
    assert.ok(item.stock - item.reserved >= 0, `available for ${sku} is negative`);
  }
}

// --- Oversold stock ---------------------------------------------------------

test('263 concurrent orders for 250 units confirm exactly 250', async () => {
  const svc = await service({ 'sneaker-limited': 250 });
  const results = await Promise.allSettled(
    Array.from({ length: 263 }, (_, i) => svc.reserve(`order-${i}`, [{ sku: 'sneaker-limited', qty: 1 }]))
  );
  const rejected = results.filter(r => r.status === 'rejected');
  assert.equal(results.length - rejected.length, 250);
  assert.equal(rejected.length, 13);
  for (const { reason } of rejected) {
    assert.ok(reason instanceof InsufficientStockError, reason);
  }
  assert.deepEqual(counters(await svc.snapshot('sneaker-limited')), { stock: 250, reserved: 250, sold: 0 });

  const confirmed = results.map((r, i) => r.status === 'fulfilled' && `order-${i}`).filter(Boolean);
  await Promise.all(confirmed.map(orderId => svc.commit(orderId)));
  assert.deepEqual(counters(await svc.snapshot('sneaker-limited')), { stock: 0, reserved: 0, sold: 250 });
});

test('restocking while orders reserve and commit loses no update', async () => {
  const svc = await service({ widget: 10 });
  await svc.reserve('o-commit', [{ sku: 'widget', qty: 2 }]);
  await Promise.all([
    svc.commit('o-commit'),
    ...Array.from({ length: 5 }, (_, i) => svc.reserve(`o${i}`, [{ sku: 'widget', qty: 1 }])),
    ...Array.from({ length: 3 }, () => svc.addStock('widget', 4))
  ]);
  assert.deepEqual(counters(await svc.snapshot('widget')), { stock: 20, reserved: 5, sold: 2 });
});

test('concurrent first restocks of a new sku are all counted', async () => {
  const svc = new InventoryService();
  await Promise.all(Array.from({ length: 10 }, () => svc.addStock('fresh', 3)));
  assert.deepEqual(counters(await svc.snapshot('fresh')), { stock: 30, reserved: 0, sold: 0 });
});

// --- Retried checkouts holding stock twice -----------------------------------

test('a retry that overlaps the original reserve holds the stock once', async () => {
  for (const gap of GAPS) {
    const svc = await service();
    const reserve = () => svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
    const [first, retry] = await race(reserve, reserve, gap);
    const reservation = { orderId: 'o1', status: 'reserved', items: [{ sku: 'widget', qty: 2 }] };
    assert.deepEqual(first.value, reservation, `gap ${gap}`);
    assert.deepEqual(retry.value, reservation, `gap ${gap}`);
    assert.equal(await svc.available('widget'), 8, `gap ${gap}`);
    await svc.release('o1');
    assert.equal(await svc.available('widget'), 10, `gap ${gap}`);
  }
});

test('a cancel sent while the timed-out reserve is still running releases its hold', async () => {
  for (const gap of GAPS) {
    const svc = await service();
    const [reserved, released] = await race(
      () => svc.reserve('o1', [{ sku: 'widget', qty: 2 }]),
      () => svc.release('o1'),
      gap
    );
    assert.equal(reserved.status, 'fulfilled', `gap ${gap}`);
    assert.equal(released.value?.status, 'released', `gap ${gap}: ${released.reason}`);
    assert.deepEqual(counters(await svc.snapshot('widget')), { stock: 10, reserved: 0, sold: 0 }, `gap ${gap}`);
  }
});

// --- Bundles left half-held ---------------------------------------------------

test('a bundle with an out-of-stock item holds none of its items', async () => {
  const svc = await service({ shoe: 5, lace: 1 });
  await assert.rejects(
    svc.reserve('o1', [{ sku: 'shoe', qty: 2 }, { sku: 'lace', qty: 2 }]),
    InsufficientStockError
  );
  assert.equal(await svc.available('shoe'), 5);
  assert.equal(await svc.available('lace'), 1);
  await assert.rejects(svc.release('o1'), UnknownOrderError);
});

test('a bundle with an unknown sku holds none of its items', async () => {
  const svc = await service({ shoe: 5 });
  await assert.rejects(svc.reserve('o1', [{ sku: 'shoe', qty: 2 }, { sku: 'nope', qty: 1 }]), UnknownSkuError);
  assert.equal(await svc.available('shoe'), 5);
});

test('bundles competing for the last units in opposite order: one wins, no partial holds, no deadlock', { timeout: 5000 }, async () => {
  for (const gap of GAPS) {
    const svc = await service({ shoe: 1, lace: 1 });
    const [a, b] = await race(
      () => svc.reserve('o1', [{ sku: 'shoe', qty: 1 }, { sku: 'lace', qty: 1 }]),
      () => svc.reserve('o2', [{ sku: 'lace', qty: 1 }, { sku: 'shoe', qty: 1 }]),
      gap
    );
    assert.deepEqual([a.status, b.status].sort(), ['fulfilled', 'rejected'], `gap ${gap}`);
    assert.ok((a.reason || b.reason) instanceof InsufficientStockError, `gap ${gap}`);
    assert.deepEqual(counters(await svc.snapshot('shoe')), { stock: 1, reserved: 1, sold: 0 }, `gap ${gap}`);
    assert.deepEqual(counters(await svc.snapshot('lace')), { stock: 1, reserved: 1, sold: 0 }, `gap ${gap}`);
  }
});

// --- reserved going negative ------------------------------------------------

test('expire leaves committed orders alone', async () => {
  let t = 0;
  const svc = await service({ widget: 10 }, { now: () => t, reservationTtlMs: 1000 });
  await svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
  await svc.commit('o1');
  t = 5000;
  assert.deepEqual(await svc.expire(), []);
  assert.deepEqual(counters(await svc.snapshot('widget')), { stock: 8, reserved: 0, sold: 2 });
  assert.equal((await svc.commit('o1')).status, 'committed');
});

test('a committed order cannot be released', async () => {
  const svc = await service();
  await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
  await svc.commit('o1');
  await assert.rejects(svc.release('o1'), OrderStateError);
  assert.deepEqual(counters(await svc.snapshot('widget')), { stock: 7, reserved: 0, sold: 3 });
});

test('overlapping releases of one order return its units once', async () => {
  for (const gap of GAPS) {
    const svc = await service();
    await svc.reserve('o1', [{ sku: 'widget', qty: 4 }]);
    const results = await race(() => svc.release('o1'), () => svc.release('o1'), gap);
    for (const r of results) assert.equal(r.value?.status, 'released', `gap ${gap}: ${r.reason}`);
    assert.deepEqual(counters(await svc.snapshot('widget')), { stock: 10, reserved: 0, sold: 0 }, `gap ${gap}`);
  }
});

test('expire racing a checkout release returns the units once', async () => {
  for (const gap of GAPS) {
    let t = 0;
    const svc = await service({ widget: 10 }, { now: () => t, reservationTtlMs: 1000 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 4 }]);
    t = 5000;
    for (const [first, second] of [[() => svc.expire(), () => svc.release('o1')], [() => svc.release('o1'), () => svc.expire()]]) {
      const results = await race(first, second, gap);
      for (const r of results) assert.equal(r.status, 'fulfilled', `gap ${gap}: ${r.reason}`);
      assert.deepEqual(counters(await svc.snapshot('widget')), { stock: 10, reserved: 0, sold: 0 }, `gap ${gap}`);
    }
  }
});

// --- sold higher than shipped -------------------------------------------------

test('overlapping commits of one order sell its units once', async () => {
  for (const gap of GAPS) {
    const svc = await service();
    await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
    const results = await race(() => svc.commit('o1'), () => svc.commit('o1'), gap);
    for (const r of results) assert.equal(r.value?.status, 'committed', `gap ${gap}: ${r.reason}`);
    assert.deepEqual(counters(await svc.snapshot('widget')), { stock: 7, reserved: 0, sold: 3 }, `gap ${gap}`);
  }
});

test('a commit racing a release either sells the units or returns them, never both', async () => {
  for (const gap of GAPS) {
    for (const commitFirst of [true, false]) {
      const svc = await service();
      await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
      const commit = () => svc.commit('o1');
      const release = () => svc.release('o1');
      const [first, second] = await race(commitFirst ? commit : release, commitFirst ? release : commit, gap);
      const label = `gap ${gap}, ${commitFirst ? 'commit' : 'release'} first`;
      assert.equal(first.status, 'fulfilled', `${label}: ${first.reason}`);
      assert.ok(second.reason instanceof OrderStateError, `${label}: second call should be rejected`);
      const want = commitFirst ? { stock: 7, reserved: 0, sold: 3 } : { stock: 10, reserved: 0, sold: 0 };
      assert.deepEqual(counters(await svc.snapshot('widget')), want, label);
    }
  }
});

test('a commit racing expire either sells the units or releases them, never both', async () => {
  for (const gap of GAPS) {
    for (const commitFirst of [true, false]) {
      let t = 0;
      const svc = await service({ widget: 10 }, { now: () => t, reservationTtlMs: 1000 });
      await svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
      t = 5000;
      const commit = () => svc.commit('o1');
      const expire = () => svc.expire();
      const results = await race(commitFirst ? commit : expire, commitFirst ? expire : commit, gap);
      const [committed, expired] = commitFirst ? results : results.reverse();
      const label = `gap ${gap}, ${commitFirst ? 'commit' : 'expire'} first`;
      assert.equal(expired.status, 'fulfilled', `${label}: ${expired.reason}`);
      const snapshot = counters(await svc.snapshot('widget'));
      if (committed.status === 'fulfilled') {
        assert.deepEqual(expired.value, [], label);
        assert.deepEqual(snapshot, { stock: 8, reserved: 0, sold: 2 }, label);
      } else {
        assert.ok(committed.reason instanceof OrderStateError, `${label}: ${committed.reason}`);
        assert.deepEqual(expired.value, ['o1'], label);
        assert.deepEqual(snapshot, { stock: 10, reserved: 0, sold: 0 }, label);
      }
    }
  }
});

test('expire reports only the reservations it released', async () => {
  let t = 0;
  const svc = await service({ widget: 10 }, { now: () => t, reservationTtlMs: 1000 });
  await svc.reserve('released', [{ sku: 'widget', qty: 1 }]);
  await svc.release('released');
  await svc.reserve('committed', [{ sku: 'widget', qty: 1 }]);
  await svc.commit('committed');
  await svc.reserve('stale', [{ sku: 'widget', qty: 1 }]);
  t = 5000;
  await svc.reserve('fresh', [{ sku: 'widget', qty: 1 }]);
  assert.deepEqual(await svc.expire(), ['stale']);
  assert.deepEqual(counters(await svc.snapshot('widget')), { stock: 9, reserved: 1, sold: 1 });
});

// --- The whole checkout flow at once ------------------------------------------

async function checkoutStorm(store, seed) {
  const random = mulberry32(seed);
  const pick = list => list[Math.floor(random() * list.length)];
  let t = 0;
  const svc = new InventoryService({ store, now: () => t, reservationTtlMs: 150 });
  const skus = ['sneaker', 'lace', 'sock', 'cap'];
  const added = {};
  for (const sku of skus) {
    await svc.addStock(sku, 6);
    added[sku] = 6;
  }
  for (let wave = 0; wave < 10; wave++) {
    const calls = [];
    for (let i = 0; i < 40; i++) {
      const orderId = `o${Math.floor(random() * 80)}`;
      const r = random();
      if (r < 0.4) {
        const items = skus.filter(() => random() < 0.4).map(sku => ({ sku, qty: 1 + Math.floor(random() * 2) }));
        calls.push(svc.reserve(orderId, items.length ? items : [{ sku: pick(skus), qty: 1 }]));
      } else if (r < 0.6) {
        calls.push(svc.commit(orderId));
      } else if (r < 0.8) {
        calls.push(svc.release(orderId));
      } else if (r < 0.9) {
        const sku = pick(skus);
        added[sku] += 2;
        calls.push(svc.addStock(sku, 2));
      } else {
        calls.push(svc.expire());
      }
    }
    for (const result of await Promise.allSettled(calls)) {
      if (result.status === 'rejected') {
        const { reason } = result;
        assert.ok(
          reason instanceof InsufficientStockError || reason instanceof UnknownOrderError || reason instanceof OrderStateError,
          `unexpected error: ${reason && reason.stack}`
        );
      }
    }
    t += 100;
  }
  await assertConsistent(store, added);
}

test('a storm of concurrent checkout calls keeps the counters consistent', async () => {
  for (const seed of [1, 2, 3, 4, 5]) {
    await checkoutStorm(new Store(), seed);
  }
});

test('the counters stay consistent on a store with different latency', async () => {
  for (const seed of [11, 12, 13, 14, 15]) {
    await checkoutStorm(new JitteryStore(seed * 7), seed);
  }
  const store = new JitteryStore(99);
  const svc = new InventoryService({ store });
  await svc.addStock('sneaker-limited', 50);
  const results = await Promise.allSettled(
