async function checkoutStorm(store, seed) {
  const random = mulberry32(seed);
  const pick = list => list[Math.floor(random() * list.length)];
  let t = 0;
  const svc = new InventoryService({ store, now: () => t, reservationTtlMs: 150 });
  const skus = ['sneaker', 'lace', 'sock', 'cap'];
  const added = {};
  for (const sku of skus) {
    await svc.addStock(sku, 6);
    added[sku] = 6;
  }
  for (let wave = 0; wave < 10; wave++) {
    const calls = [];
    for (let i = 0; i < 40; i++) {
      const orderId = `o${Math.floor(random() * 80)}`;
      const r = random();
      if (r < 0.4) {
        const items = skus.filter(() => random() < 0.4).map(sku => ({ sku, qty: 1 + Math.floor(random() * 2) }));
        calls.push(svc.reserve(orderId, items.length ? items : [{ sku: pick(skus), qty: 1 }]));
      } else if (r < 0.6) {
        calls.push(svc.commit(orderId));
      } else if (r < 0.8) {
        calls.push(svc.release(orderId));
      } else if (r < 0.9) {
        const sku = pick(skus);
        added[sku] += 2;
        calls.push(svc.addStock(sku, 2));
      } else {
        calls.push(svc.expire());
      }
    }
    for (const result of await Promise.allSettled(calls)) {
      if (result.status === 'rejected') {
        const { reason } = result;
        assert.ok(
          reason instanceof InsufficientStockError || reason instanceof UnknownOrderError || reason instanceof OrderStateError,
          `unexpected error: ${reason && reason.stack}`
        );
      }
    }
    t += 100;
  }
  await assertConsistent(store, added);
}

test('a storm of concurrent checkout calls keeps the counters consistent', async () => {
  for (const seed of [1, 2, 3, 4, 5]) {
    await checkoutStorm(new Store(), seed);
  }
});

test('the counters stay consistent on a store with different latency', async () => {
  for (const seed of [11, 12, 13, 14, 15]) {
    await checkoutStorm(new JitteryStore(seed * 7), seed);
  }
  const store = new JitteryStore(99);
  const svc = new InventoryService({ store });
  await svc.addStock('sneaker-limited', 50);
  const results = await Promise.allSettled(
    Array.from({ length: 60 }, (_, i) => svc.reserve(`order-${i}`, [{ sku: 'sneaker-limited', qty: 1 }]))
  );
  assert.equal(results.filter(r => r.status === 'fulfilled').length, 50);
  assert.equal(await svc.available('sneaker-limited'), 0);
});

test('services that share a store do not oversell', async () => {
  const store = new Store();
  const workers = [new InventoryService({ store }), new InventoryService({ store })];
  await workers[0].addStock('sneaker-limited', 10);
  const results = await Promise.allSettled(
    Array.from({ length: 20 }, (_, i) => workers[i % 2].reserve(`order-${i}`, [{ sku: 'sneaker-limited', qty: 1 }]))
  );
  assert.equal(results.filter(r => r.status === 'fulfilled').length, 10);
  assert.deepEqual(counters(await workers[1].snapshot('sneaker-limited')), { stock: 10, reserved: 10, sold: 0 });
});

// --- No service-wide lock (INC-5490) ------------------------------------------

test('calls that share no sku and no order do not wait for each other', { timeout: 5000 }, async () => {
  const store = new GatedStore();
  const svc = new InventoryService({ store });
  await svc.addStock('slow', 5);
  await svc.addStock('fast', 5);
  await svc.reserve('to-release', [{ sku: 'fast', qty: 1 }]);

  const open = store.close('sku:slow');
  let slowSettled = false;
  const slow = svc.reserve('o-slow', [{ sku: 'slow', qty: 1 }]).finally(() => { slowSettled = true; });

  await svc.reserve('o-fast', [{ sku: 'fast', qty: 1 }]);
  await svc.commit('o-fast');
  await svc.release('to-release');
  await svc.addStock('fast', 1);
  assert.deepEqual(counters(await svc.snapshot('fast')), { stock: 5, reserved: 0, sold: 1 });
  assert.equal(slowSettled, false, 'the slow reserve should still be waiting on the store');

  open();
  assert.equal((await slow).status, 'reserved');
