'use strict';

const { Store } = require('./store');
const {
  ValidationError,
  UnknownSkuError,
  UnknownOrderError,
  InsufficientStockError,
  OrderStateError
} = require('./errors');

const DEFAULT_TTL_MS = 15 * 60 * 1000;

/**
 * Stock reservations for checkout.
 *
 * Every SKU has three counters: `stock` (units on hand), `reserved` (units
 * held for orders that have not been committed) and `sold`. Available stock
 * is `stock - reserved` and must never go below zero.
 *
 * An order moves reserved -> committed, or reserved -> released. Committing
 * turns its held units into sold units; releasing returns them.
 *
 * The service is called concurrently by every checkout worker. Every change
 * runs under locks on just the order and SKUs it touches, so calls that share
 * neither run in parallel. A call takes at most one order lock, takes it
 * before any SKU lock, and takes SKU locks in sorted order, so calls cannot
 * deadlock. Locks belong to the store: services sharing a store share them.
 */
class InventoryService {
  constructor({ store = new Store(), reservationTtlMs = DEFAULT_TTL_MS, now = () => Date.now() } = {}) {
    this.store = store;
    this.ttl = reservationTtlMs;
    this.now = now;
  }

  /** Add units to a SKU, creating it if needed. Returns the SKU snapshot. */
  async addStock(sku, qty) {
    assertSku(sku);
    assertQty(qty);
    return this.#locked([skuKey(sku)], async () => {
      const item = (await this.store.get(skuKey(sku))) || { stock: 0, reserved: 0, sold: 0 };
      item.stock += qty;
      await this.store.set(skuKey(sku), item);
      return { sku, ...item };
    });
  }

  /** Units that can still be reserved. */
  async available(sku) {
    const item = await this.getItem(sku);
    return item.stock - item.reserved;
  }

  /** The SKU's counters. */
  async snapshot(sku) {
    const item = await this.getItem(sku);
    return { sku, stock: item.stock, reserved: item.reserved, sold: item.sold };
  }

  /**
   * Hold stock for an order: all of its items, or none of them.
   *
   * Idempotent by orderId: checkout retries a timed-out request with the same
   * orderId, and a retry must return the existing reservation rather than
   * hold the stock twice.
   *
   * Rejects with InsufficientStockError when any item cannot be held, and
   * then holds nothing.
   */
  async reserve(orderId, items) {
    assertOrderId(orderId);
    assertItems(items);
    const wanted = items.map(({ sku, qty }) => ({ sku, qty }));
    // The order lock makes a retry wait for the original call, then find its order.
    return this.#locked([orderKey(orderId)], async () => {
      const existing = await this.store.get(orderKey(orderId));
      if (existing) {
        return toReservation(existing);
      }
      return this.#locked(skuKeys(wanted), async () => {
        const counters = await Promise.all(wanted.map(({ sku }) => this.store.get(skuKey(sku))));
        // Check every item before holding any, so a rejected order holds nothing.
        for (const [i, { sku, qty }] of wanted.entries()) {
          if (!counters[i]) {
            throw new UnknownSkuError(sku);
          }
          const free = counters[i].stock - counters[i].reserved;
          if (free < qty) {
            throw new InsufficientStockError(sku, qty, free);
          }
        }
        wanted.forEach(({ qty }, i) => { counters[i].reserved += qty; });
        const order = { orderId, items: wanted, status: 'reserved', createdAt: this.now() };
        await setAll(this.store, [
          ...wanted.map(({ sku }, i) => [skuKey(sku), counters[i]]),
          [orderKey(orderId), order]
        ]);
        return toReservation(order);
      });
    });
  }

  /**
   * Turn a reservation into a sale. Idempotent: committing a committed order
   * returns it unchanged. A released order cannot be committed.
   */
  async commit(orderId) {
    assertOrderId(orderId);
    return this.#withOrder(orderId, order => {
      if (order.status === 'committed') {
        return toReservation(order);
      }
      if (order.status !== 'reserved') {
        throw new OrderStateError(orderId, order.status, 'commit');
      }
      return this.#settle(order, 'committed', sellHeld);
    });
  }

  /**
   * Cancel a reservation and return its units. Idempotent: releasing a
   * released order returns it unchanged. A committed order cannot be
   * released; its units have been sold.
   */
  async release(orderId) {
    assertOrderId(orderId);
    return this.#withOrder(orderId, order => {
      if (order.status === 'released') {
        return toReservation(order);
      }
      if (order.status !== 'reserved') {
        throw new OrderStateError(orderId, order.status, 'release');
      }
      return this.#settle(order, 'released', returnHeld);
    });
  }

  /**
   * Release every reservation older than the TTL that has not been committed
   * or released. Returns the orderIds it released.
   */
  async expire() {
    const cutoff = this.now() - this.ttl;
    const isStale = order => order.status === 'reserved' && order.createdAt < cutoff;
    const released = [];
    for (const key of await this.store.keys('order:')) {
      // Committed and released are final, so only a stale reservation is worth
      // locking. It is checked again under the lock, since checkout may have
      // committed or released it in the meantime.
      const order = await this.store.get(key);
      if (!order || !isStale(order)) {
        continue;
      }
      const expired = await this.#withOrder(order.orderId, async current => {
        if (!isStale(current)) {
          return false;
        }
        await this.#settle(current, 'released', returnHeld);
        return true;
      });
      if (expired) {
        released.push(order.orderId);
      }
    }
    return released;
  }

  async getItem(sku) {
    assertSku(sku);
    const item = await this.store.get(skuKey(sku));
    if (!item) {
      throw new UnknownSkuError(sku);
    }
    return item;
  }

  async getOrder(orderId) {
    assertOrderId(orderId);
    const order = await this.store.get(orderKey(orderId));
    if (!order) {
      throw new UnknownOrderError(orderId);
    }
    return order;
  }

  #locked(keys, fn) {
    return withLocks(locksFor(this.store), keys, fn);
  }

  // Runs fn with the order, read while holding its lock.
  #withOrder(orderId, fn) {
    return this.#locked([orderKey(orderId)], async () => fn(await this.getOrder(orderId)));
  }

  // Moves a reserved order to `status`, applying `update` to each of its SKUs'
  // counters. The caller holds the order's lock.
  #settle(order, status, update) {
    return this.#locked(skuKeys(order.items), async () => {
      const counters = await Promise.all(order.items.map(({ sku }) => this.getItem(sku)));
      order.items.forEach(({ qty }, i) => update(counters[i], qty));
      order.status = status;
      await setAll(this.store, [
        ...order.items.map(({ sku }, i) => [skuKey(sku), counters[i]]),
        [orderKey(order.orderId), order]
      ]);
      return toReservation(order);
    });
  }
}

function sellHeld(item, qty) {
  item.reserved -= qty;
  item.stock -= qty;
  item.sold += qty;
}

function returnHeld(item, qty) {
  item.reserved -= qty;
}

// Writes every entry, and waits for all of them even if one fails, so that no
// write is still in flight once the caller's locks are released.
async function setAll(store, entries) {
  const results = await Promise.allSettled(entries.map(([key, value]) => store.set(key, value)));
  const failed = results.find(result => result.status === 'rejected');
  if (failed) {
    throw failed.reason;
  }
}

// Lock tables by store: key -> promise that settles when the key's last
// queued holder unlocks it. Keys with nobody holding or waiting are removed.
const lockTables = new WeakMap();

function locksFor(store) {
  let locks = lockTables.get(store);
  if (!locks) {
    locks = new Map();
    lockTables.set(store, locks);
  }
  return locks;
}

// Runs fn while holding every key's lock, taking them in the order given.
async function withLocks(locks, keys, fn) {
  const unlocks = [];
  try {
    for (const key of keys) {
      unlocks.push(await lock(locks, key));
    }
    return await fn();
  } finally {
    unlocks.reverse().forEach(unlock => unlock());
  }
}

// Queues for the key's lock, first come first served. Resolves to the
// function that unlocks it.
async function lock(locks, key) {
  const previous = locks.get(key);
  let unlock;
  const current = new Promise(resolve => { unlock = resolve; });
  locks.set(key, current);
  await previous;
  return () => {
    if (locks.get(key) === current) {
      locks.delete(key);
    }
    unlock();
  };
}

function skuKey(sku) {
  return `sku:${sku}`;
}

function orderKey(orderId) {
  return `order:${orderId}`;
}

// Sorted, so that every call takes SKU locks in the same order.
function skuKeys(items) {
  return items.map(({ sku }) => skuKey(sku)).sort();
}

function toReservation(order) {
  return { orderId: order.orderId, status: order.status, items: order.items.map(({ sku, qty }) => ({ sku, qty })) };
}
EOF
