(async () => {
  // 1) Lock table cleanup: private, so inspect via a fresh store after a heavy run.
  const store = new Store();
  const svc = new InventoryService({ store });
  const N = 2000;
  for (let i = 0; i < N; i++) await svc.addStock(`sku${i}`, 5);
  let t0 = Date.now();
  await Promise.all(Array.from({ length: N }, (_, i) => svc.reserve(`o${i}`, [{ sku: `sku${i}`, qty: 1 }])));
