  // same work, one hot sku
  await svc.addStock('hot', N);
  t0 = Date.now();
  await Promise.all(Array.from({ length: N }, (_, i) => svc.reserve(`h${i}`, [{ sku: 'hot', qty: 1 }])));
  const hot = Date.now() - t0;
  console.log({ disjointMs: disjoint, hotSkuMs: hot, hotAvailable: await svc.available('hot') });
  // 2) lock map is emptied: wrap Map.prototype.set to find the lock table
  const origSet = Map.prototype.set; const maps = new Set();
  Map.prototype.set = function (k, v) { if (v instanceof Promise) maps.add(this); return origSet.call(this, k, v); };
  await Promise.all(Array.from({ length: 100 }, (_, i) => svc.commit(`o${i}`)));
  await Promise.all(Array.from({ length: 100 }, (_, i) => svc.release(`h${i}`)));
  await svc.expire();
  Map.prototype.set = origSet;
  console.log('lock tables seen:', maps.size, 'entries left:', [...maps].map(m => m.size));
})();
